<template><div class="business-summary"><p v-if="!sections.length" class="empty">{{kind==='sale'?'暂无取消或售后申请':'暂无资金执行记录'}}</p><section v-for="s in sections" :key="s.id"><h3>{{s.title}}</h3><dl><div v-for="p in s.values" :key="p[0]" :class="{wide:/规则|说明|原因|结论/.test(p[0])}"><dt>{{p[0]}}</dt><dd>{{p[1]}}</dd></div></dl><ServiceEvidence v-if="s.evidence&&s.evidence.length" :value="s.evidence" :record="record" :table="table" label="申请凭证"/><details v-if="s.extraEvidence&&s.extraEvidence.length"><summary>补充材料</summary><div v-for="(e,i) in s.extraEvidence" :key="i"><p>{{e['追加说明']}}</p><ServiceEvidence :value="e['追加证据']||[]" :record="record" :table="table" label="补充凭证"/></div></details></section><p v-if="record['分账阻断原因']" class="notice">分账提示：{{record['分账阻断原因']}}</p></div></template>
<script>
import {moneySections,saleSections} from '../../../../../prototype-shared/service/display.js';
import ServiceEvidence from './ServiceEvidence.vue';
export default {components:{ServiceEvidence},props:{record:Object,kind:String,table:String},computed:{sections(){return this.kind==='sale'?[...saleSections(this.record),...(this.table==='orders'?moneySections(this.record).filter(f=>['退款','回退'].includes(f.kind)):[])]:moneySections(this.record)}}};
</script>
<style scoped>.business-summary section{padding:16px 0;border-bottom:1px solid #edf0f4}.business-summary h3{font-size:15px;margin-bottom:12px}.business-summary dl{display:grid;grid-template-columns:1fr 1fr;gap:14px 24px}.business-summary dl>div{display:flex;gap:12px}.business-summary dt{color:#7b8592;min-width:96px}.business-summary dd{margin:0;word-break:break-word}.wide{grid-column:1/-1}.empty{color:#89939e;padding:24px 0}.notice{color:#a56d16;background:#fff7e6;padding:12px}.business-summary summary{cursor:pointer;color:#2d8cf0}</style>
